<div class="page-heading"><div><p class="eyebrow">SRI LANKA CALENDAR</p><h1>Holidays and school terms</h1><p class="muted">Official dates for the year shown below. Check the linked source for later changes.</p></div><a class="btn secondary" href="/planner">Back to planner</a></div>
<section class="card"><form class="inline" method="get" action="/planner/holidays"><label>Year<input type="number" name="year" min="2000" max="2100" value="<?= e($year) ?>" required></label><button class="secondary">View year</button></form>
<?php if (!$calendar['dataset']): ?><p class="muted">No verified Sri Lanka holiday dataset is bundled for <?= e($year) ?>. Dates for another year are not estimated.</p><?php else: $dataset=$calendar['dataset']; ?>
<p class="footnote"><?= e($dataset['year']) ?> · <?= e($dataset['revision']) ?> · Latest source published <?= e($dataset['published_on']) ?> · <a href="<?= e($dataset['source_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($dataset['source_title']) ?></a>. Base sources: <a href="https://documents.gov.lk/view/calander/2026/2026_E.pdf" target="_blank" rel="noopener noreferrer">2026 government desk calendar</a> and <a href="https://documents.gov.lk/view/extra-gazettes/2025/5/2438-22_E.pdf" target="_blank" rel="noopener noreferrer">Gazette Extraordinary 2438/22</a>. Subject to later official variation.</p>
<p class="footnote">All Saturdays and Sundays are bank holidays, even when they have no row below. This list shows named holidays only.</p>
<div class="table-wrap"><table><thead><tr><th>Date</th><th>Holiday</th><th>Applies to</th></tr></thead><tbody><?php foreach ($calendar['holidays'] as $holiday): ?><tr><td><?= e($holiday['date']) ?></td><td><strong><?= e($holiday['title_en']) ?></strong></td><td><?= e(implode(' · ',array_filter([$holiday['is_public'] ? 'Public' : null,'Bank',$holiday['is_mercantile'] ? 'Mercantile' : null,$holiday['is_poya'] ? 'Poya' : null]))) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?></section>
<section class="card"><h2>School terms</h2><?php if (!$calendar['school_terms']): ?><p class="muted">No verified school term dates are available for <?= e($year) ?> yet. School calendars vary by authority and may be revised.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Term</th><th>Dates</th><th>Authority</th></tr></thead><tbody><?php foreach ($calendar['school_terms'] as $term): ?><tr><td><?= e($term['label']) ?></td><td><?= e($term['starts_on']) ?> to <?= e($term['ends_on']) ?></td><td><a href="<?= e($term['source_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($term['authority']) ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
